// In the app: sized in rem (so the interface scale applies), class "i i-<name>" (+ extra), hidden from screen readers.
export function icon(name, size = 20, extra = "") {
  return `<svg class="i i-${name}${extra ? ` ${extra}` : ""}" width="${size / 16}rem" height="${size / 16}rem" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${ICON_PATHS[name] || ""}</svg>`;
}

// On the login screen: sized in CSS pixels, without the app's icon class.
export function iconPx(name, size = 24) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON_PATHS[name] || ""}</svg>`;
}
